using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Shell;
public sealed class CompactWindow : Window {
 readonly MonitorWindow host;bool changing,ending;string theme;Grid root;ComboBox devices;Button pin;TextBlock cpu,memory,cpuInfo,memoryInfo,gpuTitle,state,updated,empty;PixelMeter cpuMeter,memoryMeter;StackPanel gpuList;readonly List<CompactGpuRow> rows=new List<CompactGpuRow>();
 public int GpuCount{get{return rows.Count;}}public string CpuText{get{return cpu.Text;}}public string MemoryText{get{return memory.Text;}}public string StateText{get{return state.Text;}}public ComboBox DevicePicker{get{return devices;}}public Grid Surface{get{return root;}}public Button PinButton{get{return pin;}}public int RowBuilds;public bool HasGpuMessage{get{return empty.Visibility==Visibility.Visible;}}
 public CompactWindow(MonitorWindow owner){host=owner;Title="AQ Server · 迷你监控";ShowInTaskbar=false;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.CanResizeWithGrip;MinWidth=320;MinHeight=320;MaxWidth=600;MaxHeight=900;UseLayoutRounding=true;SnapsToDevicePixels=true;FontFamily=Theme.Chinese;FontSize=13;Foreground=Theme.Ink;Background=Theme.Bg;TextOptions.SetTextFormattingMode(this,TextFormattingMode.Display);TextOptions.SetTextRenderingMode(this,TextRenderingMode.ClearType);WindowChrome.SetWindowChrome(this,new WindowChrome{CaptionHeight=0,ResizeBorderThickness=new Thickness(5),CornerRadius=new CornerRadius(10),GlassFrameThickness=new Thickness(0)});
 var options=host.CompactOptions;Width=Finite(options.MiniWidth)?Math.Max(MinWidth,Math.Min(MaxWidth,options.MiniWidth)):360;Height=Finite(options.MiniHeight)?Math.Max(MinHeight,Math.Min(MaxHeight,options.MiniHeight)):480;if(options.MiniHeight==480&&host.CompactMetrics!=null&&host.CompactMetrics.Gpus.Count>2)Height=Math.Min(SystemParameters.WorkArea.Height-48,330+host.CompactMetrics.Gpus.Count*50);Topmost=options.MiniPinned;
 var area=SystemParameters.WorkArea;Left=Finite(options.MiniLeft)?options.MiniLeft:area.Right-Width-24;Top=Finite(options.MiniTop)?options.MiniTop:area.Top+24;
 // Keep a reachable header when a saved display is disconnected.
 if(Left+Width<SystemParameters.VirtualScreenLeft+80||Left>SystemParameters.VirtualScreenLeft+SystemParameters.VirtualScreenWidth-80||Top<SystemParameters.VirtualScreenTop||Top>SystemParameters.VirtualScreenTop+SystemParameters.VirtualScreenHeight-40){Left=area.Right-Width-24;Top=area.Top+24;}
 Build();LocationChanged+=(s,e)=>Remember();SizeChanged+=(s,e)=>Remember();Closing+=(s,e)=>{if(!ending){e.Cancel=true;host.HideToTray();}};PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Escape){host.Restore();e.Handled=true;}};}
 static bool Finite(double n){return !double.IsNaN(n)&&!double.IsInfinity(n);}
 void Remember(){if(!IsLoaded)return;var o=host.CompactOptions;o.MiniLeft=Left;o.MiniTop=Top;o.MiniWidth=ActualWidth;o.MiniHeight=ActualHeight;o.MiniPinned=Topmost;}
 Button Small(string title,string hint,Action action){var b=Theme.Button(title,action);b.MinHeight=30;b.Padding=new Thickness(9,5,9,5);b.FontSize=12;b.ToolTip=hint;return b;}
 void Build(){theme=Theme.Name;Resources=Theme.Resources();rows.Clear();var shell=new Border{Background=Theme.Surface,BorderBrush=Theme.Line,BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(10),Padding=new Thickness(16)};root=new Grid();shell.Child=root;Content=shell;for(int i=0;i<5;i++)root.RowDefinitions.Add(new RowDefinition{Height=i==3?new GridLength(1,GridUnitType.Star):GridLength.Auto});
 var header=new Grid{Margin=new Thickness(0,0,0,12)};header.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});for(int i=0;i<3;i++)header.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var grip=Theme.Text("资源速览",13,Theme.Ink,false,true);grip.Cursor=Cursors.SizeAll;grip.ToolTip="拖动移动窗口 · Esc 返回完整面板";grip.MouseLeftButtonDown+=(s,e)=>{if(e.ClickCount==2)host.Restore();else if(e.ButtonState==MouseButtonState.Pressed){try{DragMove();}catch(InvalidOperationException){}}};header.Children.Add(grip);
 pin=Small(Topmost?"已置顶":"置顶","切换窗口置顶",TogglePin);pin.Margin=new Thickness(8,0,6,0);Grid.SetColumn(pin,1);header.Children.Add(pin);var expand=Small("展开","返回完整面板",host.Restore);Grid.SetColumn(expand,2);header.Children.Add(expand);var close=Small("×","收起到托盘，继续采集与存档",host.HideToTray);close.Margin=new Thickness(6,0,0,0);Grid.SetColumn(close,3);header.Children.Add(close);root.Children.Add(header);
 devices=new ComboBox{MinHeight=34,FontFamily=Theme.Chinese,FontSize=12,Margin=new Thickness(0,0,0,14),DisplayMemberPath="Name",ToolTip="切换本机或服务器；所有设备仍持续采集"};Grid.SetRow(devices,1);root.Children.Add(devices);devices.SelectionChanged+=(s,e)=>{if(!changing&&devices.SelectedItem is Server)host.ChooseServer((Server)devices.SelectedItem);};
 var summary=new Grid{Margin=new Thickness(0,0,0,14)};summary.ColumnDefinitions.Add(new ColumnDefinition());summary.ColumnDefinitions.Add(new ColumnDefinition());var left=Tile("CPU",out cpu,out cpuInfo,out cpuMeter,Theme.Green);left.Margin=new Thickness(0,0,5,0);summary.Children.Add(left);var right=Tile("内存",out memory,out memoryInfo,out memoryMeter,Theme.Teal);right.Margin=new Thickness(5,0,0,0);Grid.SetColumn(right,1);summary.Children.Add(right);Grid.SetRow(summary,2);root.Children.Add(summary);
 var gpuArea=new Grid();gpuArea.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});gpuArea.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});gpuTitle=Theme.Text("GPU",12,Theme.Muted,false,true);gpuTitle.Margin=new Thickness(0,0,0,8);gpuArea.Children.Add(gpuTitle);var scroll=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto,HorizontalScrollBarVisibility=ScrollBarVisibility.Disabled,Padding=new Thickness(0,0,4,0)};Grid.SetRow(scroll,1);gpuArea.Children.Add(scroll);gpuList=new StackPanel();scroll.Content=gpuList;empty=Theme.Text("等待采集",12,Theme.Muted);empty.TextWrapping=TextWrapping.Wrap;gpuList.Children.Add(empty);Grid.SetRow(gpuArea,3);root.Children.Add(gpuArea);
 var footer=new StackPanel{Margin=new Thickness(0,12,0,0)};state=Theme.Text("等待连接",11,Theme.Muted);state.ToolTip="窗口收起后，所有设备仍在后台采集并存档。";updated=Theme.Text("",11,Theme.Muted);updated.Margin=new Thickness(0,4,0,0);footer.Children.Add(state);footer.Children.Add(updated);Grid.SetRow(footer,4);root.Children.Add(footer);RefreshDevices();}
 Border Tile(string title,out TextBlock value,out TextBlock info,out PixelMeter meter,Brush color){var content=new StackPanel();content.Children.Add(Theme.Text(title,11,Theme.Muted));value=Theme.Text("—",23,color,false,true);value.Margin=new Thickness(0,4,0,0);content.Children.Add(value);meter=new PixelMeter(0,color,4){Margin=new Thickness(0,8,0,8),Blocks=16};content.Children.Add(meter);info=Theme.Text("等待采集",11,Theme.Muted);content.Children.Add(info);return new Border{CornerRadius=new CornerRadius(7),Background=Theme.Bg,Padding=new Thickness(12),Child=content};}
 public void RefreshDevices(){changing=true;devices.ItemsSource=null;devices.ItemsSource=host.CompactDevices.ToArray();devices.SelectedItem=host.CompactSelected;changing=false;}
 public void TogglePin(){Topmost=!Topmost;pin.Content=Topmost?"已置顶":"置顶";Remember();host.CompactOptions.MiniPinned=Topmost;}
 public void RefreshAppearance(){Build();Update(host.CompactMetrics,host.CompactTimestamp);}
 public void Update(Metrics m,DateTime? time){if(theme!=Theme.Name){RefreshAppearance();return;}if(!host.CompactDevices.SequenceEqual(devices.Items.Cast<Server>()))RefreshDevices();if(!object.ReferenceEquals(devices.SelectedItem,host.CompactSelected)){changing=true;devices.SelectedItem=host.CompactSelected;changing=false;}bool okay=m!=null&&string.IsNullOrWhiteSpace(m.Error);var statusMetrics=m;if(!okay)m=host.CompactDisplayMetrics;bool display=m!=null&&string.IsNullOrWhiteSpace(m.Error);NumericMotion.Text(cpu,display?m.Cpu:"—");double usage=display?ResourceSample.MemoryPercent(m.Mem):double.NaN;NumericMotion.Text(memory,double.IsNaN(usage)?"—":usage.ToString("0.0",CultureInfo.InvariantCulture)+"%");cpuInfo.Text=display?m.Cores+" 个逻辑处理器":"等待有效采样";memoryInfo.Text=display?ResourceSample.MemoryLabel(m.Mem):"等待有效采样";memoryInfo.ToolTip=display?m.Mem:"未采集";cpuMeter.Value=display?ResourceSample.ParsePercent(m.Cpu):0;memoryMeter.Value=double.IsNaN(usage)?0:usage;
 var gpus=display?m.Gpus:new List<Gpu>();bool same=rows.Count==gpus.Count&&rows.Select(x=>x.Id).SequenceEqual(gpus.Select(x=>x.Index));if(!same){foreach(var row in rows)gpuList.Children.Remove(row);rows.Clear();foreach(var gpu in gpus){var row=new CompactGpuRow(gpu);rows.Add(row);gpuList.Children.Add(row);RowBuilds++;}}for(int i=0;i<gpus.Count;i++)rows[i].Update(gpus[i]);empty.Visibility=gpus.Count==0?Visibility.Visible:Visibility.Collapsed;empty.Text=display?"未检测到 NVIDIA GPU\nCPU 与内存继续监控。":"等待有效采样后显示显卡信息。";gpuTitle.Text=gpus.Count==0?"GPU":("GPU · "+gpus.Count+" 张显卡");m=statusMetrics;state.Text=okay?"● 已连接 · "+host.CompactArchiveStatus:(m==null?"● 正在连接":"● "+(m.Error.StartsWith("正在连接")?"正在连接":"连接异常"));state.Foreground=okay?Theme.Green:m==null?Theme.Muted:Theme.Red;state.ToolTip=okay?host.CompactArchiveStatus:m==null?"等待采集":m.Error;updated.Text=(time.HasValue?"采样 "+time.Value.ToLocalTime().ToString("HH:mm:ss"):"尚无采样")+" · 每 "+host.PollSeconds+" 秒更新";}
 public void End(){ending=true;Remember();Close();}
 public void RenderImage(string path,int width,int height,int dpi){Snapshot.Save(root,path,width,height,dpi,null);}
}
public sealed class CompactGpuRow : Border {
 public readonly string Id;TextBlock name,value,detail;PixelMeter meter;
 public CompactGpuRow(Gpu gpu){Id=gpu.Index;Background=Theme.Bg;CornerRadius=new CornerRadius(6);Padding=new Thickness(10,5,10,5);Margin=new Thickness(0,0,0,5);var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});for(int i=0;i<3;i++)grid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});name=Theme.Text("GPU "+Id,12,Theme.Ink,false,true);grid.Children.Add(name);value=Theme.Text("",12,Theme.Green,false,true);value.HorizontalAlignment=HorizontalAlignment.Right;Grid.SetColumn(value,1);grid.Children.Add(value);meter=new PixelMeter(0,Theme.Green,3){Blocks=28,Margin=new Thickness(0,4,0,4)};Grid.SetRow(meter,1);Grid.SetColumnSpan(meter,2);grid.Children.Add(meter);detail=Theme.Text("",11,Theme.Muted);Grid.SetRow(detail,2);Grid.SetColumnSpan(detail,2);grid.Children.Add(detail);Child=grid;Update(gpu);}
 public void Update(Gpu gpu){double v=GpuCard.Number(gpu.Util),temp=GpuCard.Number(gpu.Temp);var color=temp>=75?Theme.Red:v>=80?Theme.Amber:Theme.Green;NumericMotion.Text(value,GpuTelemetry.Unit(gpu.Util,"%"));value.Foreground=meter.Fill=color;meter.Value=v;NumericMotion.Text(detail,Memory(gpu.Used)+" / "+Memory(gpu.Total)+" GiB  ·  "+GpuTelemetry.Unit(gpu.Temp,"°C"));ToolTip="GPU "+gpu.Index+" · "+gpu.Name+"\n显存："+gpu.Used+" / "+gpu.Total+" MiB\n功耗："+GpuTelemetry.Power(gpu);}
 static string Memory(string raw){return GpuTelemetry.Available(raw)?(GpuCard.Number(raw)/1024).ToString("0.0",CultureInfo.InvariantCulture):"—";}
}
